from __future__ import annotations

from datetime import datetime
from decimal import Decimal, ROUND_HALF_UP
from typing import Iterable


def normalize_name(value: str) -> str:
    return ' '.join(part.capitalize() for part in value.strip().split())


def parse_amount(value: str | int | float) -> Decimal:
    return Decimal(str(value)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)


def summarize_orders(orders: Iterable[dict]) -> dict:
    total = Decimal('0.00')
    count = 0
    for order in orders:
        total += parse_amount(order['amount'])
        count += 1
    average = (total / count).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) if count else Decimal('0.00')
    return {
        'count': count,
        'total_amount': str(total),
        'average_amount': str(average),
        'generated_at': datetime.utcnow().isoformat() + 'Z',
    }
