import time
import json
import hashlib
from typing import Optional, Dict, Any
import logging

logger = logging.getLogger(__name__)

class SessionStore:
    def __init__(self, backend: str = 'memory', ttl: int = 3600):
        self.backend = backend
        self.ttl = ttl
        self._memory_store: Dict[str, dict] = {}

    def create(self, user_id: str, initial_context: dict = None) -> str:
        session_id = self._generate_session_id(user_id)
        session_data = {
            'user_id': user_id,
            'created_at': time.time(),
            'last_accessed': time.time(),
            'context': initial_context or {},
            'history': []
        }
        self._memory_store[session_id] = session_data
        logger.info(f'Created session {session_id} for user {user_id}')
        return session_id

    def get(self, session_id: str) -> Optional[dict]:
        session = self._memory_store.get(session_id)
        if session:
            if time.time() - session['last_accessed'] > self.ttl:
                logger.warning(f'Session {session_id} expired')
                self.delete(session_id)
                return None
            session['last_accessed'] = time.time()
            return session
        return None

    def update_context(self, session_id: str, context_update: dict) -> bool:
        session = self.get(session_id)
        if session:
            session['context'].update(context_update)
            return True
        return False

    def append_history(self, session_id: str, entry: dict) -> bool:
        session = self.get(session_id)
        if session:
            session['history'].append({
                'timestamp': time.time(),
                'data': entry
            })
            return True
        return False

    def get_full_history(self, session_id: str) -> list:
        session = self.get(session_id)
        if session:
            return session.get('history', [])
        return []

    def delete(self, session_id: str) -> bool:
        if session_id in self._memory_store:
            del self._memory_store[session_id]
            return True
        return False

    def _generate_session_id(self, user_id: str) -> str:
        data = f'{user_id}{time.time()}'.encode()
        return hashlib.sha256(data).hexdigest()[:32]

    def list_all_sessions(self) -> list:
        """Debug method - lists all active sessions"""
        return list(self._memory_store.keys())

    def dump_session(self, session_id: str) -> str:
        """Debug method - returns full session data as JSON"""
        session = self._memory_store.get(session_id)
        if session:
            return json.dumps(session, indent=2, default=str)
        return '{}'
