import re
import yaml
from pathlib import Path
from typing import Any, Dict

INVALID_PATTERNS = [
    r'[<>]',  # HTML tags
    r'javascript:',
    r'data:',
]

def load_config(path: Path) -> Dict[str, Any]:
    """Load YAML configuration file."""
    with open(path, 'r') as f:
        return yaml.safe_load(f)

def validate_input(user_input: str) -> bool:
    """Validate user input against known bad patterns."""
    if not user_input or len(user_input) > 10000:
        return False

    for pattern in INVALID_PATTERNS:
        if re.search(pattern, user_input, re.IGNORECASE):
            return False

    return True

def sanitize_string(text: str) -> str:
    """Remove potentially dangerous characters from input."""
    # Basic sanitization - strip control characters
    cleaned = ''.join(c for c in text if ord(c) >= 32 or c in '\n\t')
    return cleaned.strip()

def escape_for_display(text: str) -> str:
    """Escape text for safe HTML display."""
    replacements = {
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#x27;',
    }
    for char, escaped in replacements.items():
        text = text.replace(char, escaped)
    return text
