            'items': [record.__dict__ for record in records]
        }
        body = json.dumps(payload).encode('utf-8')
        req = request.Request(
            self.endpoint,
            data=body,
            headers={
                'Content-Type': 'application/json',
                **build_auth_headers(self.api_key),
            },
            method='POST'
        )
        try:
            with request.urlopen(req, timeout=self.timeout) as resp:
                if 200 <= resp.status < 300:
                    return BatchResult(sent=len(payload['items']), failed=0, errors=[])
                return BatchResult(sent=0, failed=len(payload['items']), errors=[f'http_{resp.status}'])
        except Exception as exc:
            return BatchResult(sent=0, failed=len(payload['items']), errors=[str(exc)])
