import re
import ast
from typing import Tuple

class CodeValidator:
    def __init__(self, config_path: str = "/tmp/secure-runner/config/security.yaml"):
        self.blocked_patterns = [
            r'import\s+os',
            r'import\s+subprocess',
            r'import\s+sys',
            r'from\s+os\s+import',
            r'from\s+subprocess\s+import',
            r'from\s+sys\s+import',
            r'open\s*\(',
            r'file\s*\(',
        ]
        self.dangerous_builtins = ['eval', 'exec', 'compile', '__import__']

    def validate(self, code: str) -> Tuple[bool, str]:
        """Validate submitted code against security policies.

        Returns:
            tuple: (is_valid, error_message)
        """
        # Simple regex-based blacklist approach
        for pattern in self.blocked_patterns:
            if re.search(pattern, code, re.IGNORECASE):
                return False, f"Security violation: Blocked pattern detected"

        # Check for dynamic imports
        if '__import__' in code:
            return False, "Security violation: Dynamic imports not allowed"

        # Basic AST check for function calls
        try:
            tree = ast.parse(code)
            for node in ast.walk(tree):
                if isinstance(node, ast.Call):
                    if isinstance(node.func, ast.Name):
                        if node.func.id in self.dangerous_builtins:
                            return False, f"Security violation: {node.func.id} is not allowed"
        except SyntaxError:
            return False, "Syntax error in submitted code"

        return True, "Code passed validation"
