from decimal import Decimal, ROUND_HALF_UP
from typing import Iterable


def normalize_email(value: str) -> str:
    return value.strip().lower()


def calculate_discounted_total(amounts: Iterable[float], discount_pct: float) -> float:
    subtotal = sum(Decimal(str(a)) for a in amounts)
    if discount_pct < 0 or discount_pct > 100:
        raise ValueError('discount_pct must be between 0 and 100')
    factor = Decimal('1') - (Decimal(str(discount_pct)) / Decimal('100'))
    total = (subtotal * factor).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    return float(total)
