import os
import yaml
import logging
from typing import Dict, Any
from pydantic_settings import BaseSettings, SettingsConfigDict
from pydantic import Field

logger = logging.getLogger(__name__)

class Settings(BaseSettings):
    model_config = SettingsConfigDict(
        env_prefix='PIPELINE_',
        env_nested_delimiter='__',
        extra='ignore'
    )

    app: Dict[str, Any] = Field(default_factory=dict)
    database: Dict[str, Any] = Field(default_factory=dict)
    processing: Dict[str, Any] = Field(default_factory=dict)
    features: Dict[str, Any] = Field(default_factory=dict)

    _config_path: str = '/tmp/project/config/settings.yaml'
    _loaded: bool = False

    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self._load_from_yaml()

    def _load_from_yaml(self):
        try:
            if os.path.exists(self._config_path):
                with open(self._config_path, 'r') as f:
                    data = yaml.safe_load(f)
                    if data:
                        for key in ['app', 'database', 'processing', 'features']:
                            if key in data:
                                setattr(self, key, data[key])
                        self._loaded = True
        except Exception as e:
            logger.error(f"Initial config load failed: {e}")

    def reload(self):
        """Reload configuration from YAML without restarting the application."""
        try:
            if not os.path.exists(self._config_path):
                logger.warning(f"Config file {self._config_path} not found, keeping current settings")
                return

            with open(self._config_path, 'r') as f:
                data = yaml.safe_load(f)
                if data is None:
                    raise ValueError("Empty YAML file")

                # Store old values in case we need to rollback
                old_data = {
                    'app': self.app.copy(),
                    'database': self.database.copy(),
                    'processing': self.processing.copy(),
                    'features': self.features.copy()
                }

                for key in ['app', 'database', 'processing', 'features']:
                    if key in data:
                        setattr(self, key, data[key])

                logger.info("Configuration reloaded successfully")

        except yaml.YAMLError as e:
            logger.warning(f"YAML parsing error during reload, keeping previous config: {e}")
        except Exception as e:
            logger.warning(f"Failed to reload config, keeping previous settings: {e}")

    def get_feature_flags(self) -> Dict[str, Any]:
        """Return feature flags for A/B testing and gradual rollouts."""
        return self.features.copy()

# Global instance
