"""
Health check script for CI/CD pipeline and container orchestration.
Called every 10 seconds by Kubernetes liveness probe.
"""
import os
import sys
import json
import logging
from pathlib import Path
from urllib.parse import urlparse

# Setup path for imports
sys.path.insert(0, '/tmp/project/src')

from config import config, Settings

logging.basicConfig(level=logging.WARNING)
logger = logging.getLogger('health_check')

def check_config_loading() -> tuple[bool, str]:
    """Verify configuration loads without errors."""
    try:
        # Force reload to ensure config is readable
        settings = Settings()
        if not settings.app.get('name'):
            return False, "Missing app name in config"
        return True, "Config loaded"
    except Exception as e:
        return False, f"Config error: {str(e)}"

def check_database_url() -> tuple[bool, str]:
    """Validate database URL format without connecting."""
    try:
        db_config = config.database
        url = db_config.get('url', '').replace('${DB_PASSWORD}', 'dummy')

        if not url:
            return True, "No database URL configured (optional)"

        parsed = urlparse(url)
        if not all([parsed.scheme, parsed.hostname]):
            return False, "Invalid database URL format"

        if parsed.scheme not in ['postgres', 'postgresql', 'mysql', 'sqlite']:
            return False, f"Unsupported DB scheme: {parsed.scheme}"

        return True, "Database URL valid"
    except Exception as e:
        return False, f"DB URL parse error: {str(e)}"

def check_cache_writable() -> tuple[bool, str]:
    """Ensure cache directory exists and is writable."""
    cache_dir = Path('/tmp/project/.cache')
    try:
        cache_dir.mkdir(parents=True, exist_ok=True)
        test_file = cache_dir / '.health_check_write_test'
        test_file.write_text('test')
        test_file.unlink()
        return True, "Cache directory writable"
    except Exception as e:
        return False, f"Cache directory not writable: {str(e)}"

def check_input_data() -> tuple[bool, str]:
    """Verify input data directory has content."""
    data_dir = Path('/tmp/project/data')
    try:
        if not data_dir.exists():
            return False, "Data directory missing"

        files = list(data_dir.glob('*.json'))
        if not files:
            return True, "No JSON files (warning)"

        return True, f"Found {len(files)} input files"
    except Exception as e:
        return False, f"Data check error: {str(e)}"

def main():
    """Run all health checks and report status."""
    checks = {
        "config": check_config_loading(),
        "database_url": check_database_url(),
        "cache_writable": check_cache_writable(),
        "input_data": check_input_data()
    }

    all_passed = all(result[0] for result in checks.values())

    status = {
        "status": "HEALTHY" if all_passed else "UNHEALTHY",
        "timestamp": config.app.get('version', 'unknown'),
        "checks": {name: {"pass": result[0], "message": result[1]} 
                  for name, result in checks.items()}
    }

    print(json.dumps(status, indent=2))

    if not all_passed:
        logger.error("Health check failed")
        sys.exit(1)

    sys.exit(0)

if __name__ == '__main__':
    main()

