import requests
from typing import Dict, List, Any
import time

class APIClient:
    def __init__(self, endpoint: str, api_key: str, max_retries: int = 3, timeout: int = 30):
        self.endpoint = endpoint.rstrip("/")
        self.api_key = api_key
        self.max_retries = max_retries
        self.timeout = timeout
        self.session = requests.Session()
        self.session.headers.update({
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json"
        })

    def healthcheck(self) -> bool:
        """Check API connectivity."""
        response = self._request("GET", "/health")
        return response.get("status") == "healthy"

    def fetch_pending_tasks(self) -> List[Dict[str, Any]]:
        """Fetch pending tasks from the queue."""
        response = self._request("GET", "/tasks/pending")
        return response.get("tasks", [])

    def execute_task(self, task: Dict[str, Any]) -> Dict[str, Any]:
        """Execute a task and return the result."""
        return self._request("POST", f"/tasks/{task['id']}/execute", json=task)

    def _request(self, method: str, path: str, **kwargs) -> Dict[str, Any]:
        """Make an HTTP request with retry logic."""
        url = f"{self.endpoint}{path}"

        for attempt in range(self.max_retries):
            try:
                response = self.session.request(
                    method, url, timeout=self.timeout, **kwargs
                )
                response.raise_for_status()
                return response.json()
            except requests.exceptions.RequestException as e:
                if attempt == self.max_retries - 1:
                    raise ConnectionError(f"Failed after {self.max_retries} attempts: {e}")
                time.sleep(2 ** attempt)  # Exponential backoff

        return {}
