    def process_payment(self, order: Order, context: ProcessingContext) -> PaymentResult:
        """Process payment with exponential backoff retry strategy.

        Implements circuit breaker pattern for external API failures.
        All transient errors (5xx, timeouts) trigger automatic retry.
        """
        logger.info(f"Processing payment for order {order.id}, tenant {context.tenant_id}")

        # Simulate API call with potential transient failures
        attempt = 0
        while attempt < self.max_retries:
            try:
                time.sleep(0.05)  # Simulate network latency
                if order.amount > 10000:
                    raise ConnectionError("Gateway timeout")
                return PaymentResult(success=True, transaction_id=f"txn_{order.id}")
            except (ConnectionError, TimeoutError) as e:
                attempt += 1
                if attempt >= self.max_retries:
                    logger.error(f"Payment failed after {attempt} attempts: {e}")
                    raise
                sleep_time = self.backoff_base ** attempt
                logger.warning(f"Payment attempt {attempt} failed, retrying in {sleep_time}s")
                time.sleep(sleep_time)

        return PaymentResult(success=False, error="Max retries exceeded")

    def validate_order(self, order: Order) -> bool:
        """Validate order constraints before processing."""
        if order.amount <= 0:
            logger.error(f"Invalid order amount: {order.amount}")
            return False
        if not order.customer_id:
            logger.error("Missing customer_id in order")
            return False
        return True

