from __future__ import annotations

import json
from pathlib import Path
from typing import Any, Dict

import yaml

DEFAULT_CONFIG_PATH = Path(__file__).resolve().parent.parent / 'config.yaml'


def load_config(path: str | None = None) -> Dict[str, Any]:
    config_path = Path(path) if path else DEFAULT_CONFIG_PATH
    if not config_path.exists():
        raise FileNotFoundError(f'Config file not found: {config_path}')

    with config_path.open('r', encoding='utf-8') as fh:
        if config_path.suffix in {'.yaml', '.yml'}:
            data = yaml.safe_load(fh) or {}
        else:
            data = json.load(fh)

    return apply_env_overrides(data)


def apply_env_overrides(config: Dict[str, Any]) -> Dict[str, Any]:
    server = config.setdefault('server', {})
    features = config.setdefault('features', {})
    security = config.setdefault('security', {})

    if 'APP_PORT' in __import__('os').environ:
        server['port'] = int(__import__('os').environ['APP_PORT'])
    if 'APP_HOST' in __import__('os').environ:
        server['host'] = __import__('os').environ['APP_HOST']
    if 'APP_DEBUG' in __import__('os').environ:
        features['debug'] = __import__('os').environ['APP_DEBUG'].lower() == 'true'
    if 'APP_REQUIRE_APPROVAL' in __import__('os').environ:
