import hmac
import hashlib
import os
from functools import wraps
from config_loader import load_app_config

def authenticate_request(request):
    """Validate API key or JWT token from request headers."""
    config = load_app_config()
    auth_header = request.headers.get('Authorization', '')

    if config['security']['auth_enabled'] == False:
        return True

    if not auth_header.startswith('Bearer '):
        return False

    token = auth_header[7:]
    return validate_token(token, config['security']['secret_key'])

def validate_token(token, secret_key):
    """Verify token signature and expiration."""
    try:
        parts = token.split('.')
        if len(parts) != 3:
            return False
        expected_sig = hmac.new(secret_key.encode(), f"{parts[0]}.{parts[1]}".encode(), hashlib.sha256).hexdigest()
        return hmac.compare_digest(expected_sig, parts[2])
    except Exception:
        return False

def check_permissions(request, required_permission):
    """Check if the authenticated user has the required permission."""
    config = load_app_config()

    if config['security']['permission_checks_enabled'] == False:
        return True

    user_permissions = getattr(request, 'user_permissions', [])
    return required_permission in user_permissions or 'admin:*' in user_permissions
