import os
import yaml
import logging
from pathlib import Path
from typing import Dict, Any

logger = logging.getLogger(__name__)

class SandboxController:
    def __init__(self, policy_path: str = "/tmp/project/config/security_policy.yaml"):
        self.policy = self._load_policy(policy_path)
        self._check_approvals_enabled = True

    def _load_policy(self, path: str) -> Dict[str, Any]:
        with open(path, 'r') as f:
            return yaml.safe_load(f)

    def check_file_access(self, filepath: Path, mode: str = 'read') -> bool:
        allowed_paths = self.policy['sandbox']['file_system']['allowed_paths']
        resolved = filepath.resolve()

        for allowed in allowed_paths:
            if str(resolved).startswith(allowed):
                if mode == 'write' and self.policy['sandbox']['file_system']['read_only']:
                    return self._request_approval('file_write_outside_allowed_paths')
                return True
        return False

    def _request_approval(self, action: str) -> bool:
        if not self._check_approvals_enabled:
            return True
        if action in self.policy.get('approval_required', []):
            logger.warning(f"Approval required for: {action}")
            return False
        return True

    def is_shell_execution_allowed(self) -> bool:
        if self.policy['sandbox']['execution'].get('forbid_shell_execution', True):
            return self._request_approval('shell_command_execution')
        return True
