def revenue_by_category(df):
    """Calculate total revenue per product category."""
    return df.groupby('category')['revenue'].agg(['sum', 'mean', 'count']).round(2)

def revenue_by_region(df):
    """Calculate total revenue per region."""
    return df.groupby('region')['revenue'].sum().sort_values(ascending=False)

def top_customers(df, n=5):
    """Identify top N customers by total spend."""
    return df.groupby('customer_id')['revenue'].sum().nlargest(n)

def daily_trends(df):
    """Calculate daily revenue trends."""
    daily = df.groupby('date')['revenue'].sum()
    return {
        'mean': daily.mean(),
        'std': daily.std(),
        'min': daily.min(),
        'max': daily.max(),
        'trend': 'increasing' if daily.iloc[-1] > daily.iloc[0] else 'decreasing'
    }

def customer_segmentation(df, customers_df):
