import pandas as pd
import numpy as np
from datetime import datetime

def analyze_regional_performance(csv_path):
    """Generate regional statistics and anomaly detection."""
    df = pd.read_csv(csv_path)
    df['date'] = pd.to_datetime(df['date'])
    df['month'] = df['date'].dt.to_period('M')

    # Regional aggregation
    regional_stats = df.groupby('region').agg({
        'amount': ['sum', 'mean', 'std', 'count'],
        'quantity': 'sum'
    }).round(2)
    regional_stats.columns = ['total_revenue', 'avg_order_value', 'std_amount', 'order_count', 'total_units']

    # Month-over-month calculation
    monthly_regional = df.groupby(['region', 'month'])['amount'].sum().unstack()
    if '2024-11' in monthly_regional.columns and '2024-12' in monthly_regional.columns:
        monthly_regional['mom_change'] = ((monthly_regional['2024-12'] - monthly_regional['2024-11']) / monthly_regional['2024-11'] * 100).round(2)
        declining_regions = monthly_regional[monthly_regional['mom_change'] < -15].index.tolist()
    else:
        declining_regions = []

    # Anomaly detection (3 sigma rule)
    anomalies = []
    for region in df['region'].unique():
        region_data = df[df['region'] == region]['amount']
        mean = region_data.mean()
        std = region_data.std()
        threshold = mean + (3 * std)
        outliers = df[(df['region'] == region) & (df['amount'] > threshold)]
        if len(outliers) > 0:
            anomalies.extend([
                {'region': region, 'transaction_id': row['transaction_id'], 'amount': row['amount'], 'threshold': threshold}
                for _, row in outliers.iterrows()
            ])

    return {
        'regional_statistics': regional_stats.to_dict(),
        'declining_regions': declining_regions,
        'anomalies': anomalies,
        'report_date': datetime.now().isoformat()
    }

if __name__ == "__main__":
    import sys
    result = analyze_regional_performance(sys.argv[1])
    print(f"Regional Analysis Report - {result['report_date']}\n")
    print("="*60)
    print("REVENUE BY REGION:")
    for region, stats in result['regional_statistics'].items():
        print(f"  {region}: ${stats['total_revenue']:,.2f} ({stats['order_count']} orders, AOV: ${stats['avg_order_value']:.2f})")

    if result['declining_regions']:
        print(f"\nWARNING: Declining regions (>15% MoM): {', '.join(result['declining_regions'])}")
    else:
        print("\nNo regions showing >15% month-over-month decline.")

    if result['anomalies']:
        print(f"\nFLAGGED ANOMALIES (3-sigma outliers): {len(result['anomalies'])} transactions")
        for a in result['anomalies']:
            print(f"  {a['transaction_id']}: ${a['amount']:.2f} in {a['region']} (threshold: ${a['threshold']:.2f})")
