"""Data validation utilities."""
import pandas as pd

def check_nulls(df, critical_cols):
    """Report null values in critical columns."""
    issues = []
    for col in critical_cols:
        null_count = df[col].isnull().sum()
        if null_count > 0:
            issues.append({'column': col, 'null_count': null_count, 'pct': null_count/len(df)*100})
    return issues

def check_duplicates(df, key_cols):
    """Check for duplicate records by key."""
    dupes = df[df.duplicated(subset=key_cols, keep=False)]
    return dupes

def validate_ranges(df, rules):
    """Validate numeric columns are within expected ranges."""
    violations = []
    for col, (min_val, max_val) in rules.items():
        out_of_range = df[(df[col] < min_val) | (df[col] > max_val)]
        if len(out_of_range) > 0:
            violations.append({'column': col, 'count': len(out_of_range)})
    return violations
