"""Data validation utilities."""

import pandas as pd
from typing import Dict, List

def check_missing_values(df: pd.DataFrame) -> Dict[str, int]:
    """Return count of missing values per column."""
    return df.isnull().sum().to_dict()

def check_duplicates(df: pd.DataFrame, key_cols: List[str]) -> int:
    """Return count of duplicate rows based on key columns."""
    return df.duplicated(subset=key_cols).sum()

def validate_date_range(df: pd.DataFrame, date_col: str, 
                        start: str, end: str) -> bool:
    """Check if all dates fall within expected range."""
    dates = pd.to_datetime(df[date_col])
    return (dates >= start).all() and (dates <= end).all()

def validate_numeric_range(df: pd.DataFrame, col: str,
                           min_val: float, max_val: float) -> pd.Series:
    """Return rows where values are outside expected range."""
    return df[(df[col] < min_val) | (df[col] > max_val)]
