    """Aggregate sales metrics by region."""
    return df.groupby('region').agg({
        'transaction_id': 'count',
        'total_amount': 'sum',
        'customer_id': 'nunique'
    }).round(2)

def top_products(df: pd.DataFrame, n: int = 5) -> pd.DataFrame:
    """Get top N products by revenue."""
    return df.groupby(['product_id', 'product_name']).agg({
        'quantity': 'sum',
        'total_amount': 'sum'
    }).nlargest(n, 'total_amount').round(2)

def daily_trends(df: pd.DataFrame) -> pd.DataFrame:
    """Calculate daily sales trends."""
    daily = df.groupby('date').agg({
        'transaction_id': 'count',
        'total_amount': 'sum'
    })
    daily['rolling_avg'] = daily['total_amount'].rolling(3).mean()
    return daily.round(2)

def payment_method_breakdown(df: pd.DataFrame) -> Dict:
