#!/usr/bin/env python3
import pandas as pd
import json
import yaml
import sys
from pathlib import Path
from datetime import datetime

def load_config(config_path):
    with open(config_path, 'r') as f:
        return yaml.safe_load(f)

def load_data(config):
    source = config['source']
    df = pd.read_csv(source['path'], encoding=source['encoding'])
    print(f"Loaded {len(df)} rows from {source['path']}")
    return df

def apply_date_filter(df, config):
    date_range = config['date_range']
    df['date'] = pd.to_datetime(df['date'])
    mask = (df['date'] >= date_range['start']) & (df['date'] <= date_range['end'])
    filtered = df[mask]
    print(f"Date filter applied: {len(filtered)} rows in range {date_range['start']} to {date_range['end']}")
    return filtered

def apply_transformations(df, config):
    for transform in config['transformations']:
        if transform['name'] == 'normalize_currency':
            for col in transform['columns']:
                df[col] = df[col].round(transform['precision'])
        elif transform['name'] == 'trim_whitespace':
            for col in transform['columns']:
                df[col] = df[col].str.strip()
        elif transform['name'] == 'deduplicate':
            df = df.drop_duplicates(subset=transform['subset'], keep=transform['keep'])
    return df

def run_quality_checks(df, config):
    warnings = []
    errors = []

    for check in config['quality_checks']:
        if check['type'] == 'range':
            col = check['column']
            invalid = df[(df[col] < check['min']) | (df[col] > check['max'])]
            if len(invalid) > 0:
                msg = f"Range check failed for {col}: {len(invalid)} rows out of range"
                if check['severity'] == 'error':
                    errors.append(msg)
                else:
                    warnings.append(msg)
        elif check['type'] == 'not_null':
            for col in check['columns']:
                invalid = df[df[col].isnull()]
                if len(invalid) > 0:
                    errors.append(f"Null check failed for {col}: {len(invalid)} null values")

    return warnings, errors

def main():
    config_path = Path('/tmp/analysis/config/pipeline.yaml')
    config = load_config(config_path)

    print(f"Running ETL pipeline: {config['etl_config']['name']}")

    df = load_data(config)
    df = apply_date_filter(df, config)
    df = apply_transformations(df, config)
    warnings, errors = run_quality_checks(df, config)

    if warnings:
        for w in warnings:
            print(f"WARNING: {w}")
    if errors:
        for e in errors:
            print(f"ERROR: {e}")
        sys.exit(1)

    output_path = config['output']['path']
    df.to_csv(output_path, index=config['output'].get('index', False))
    print(f"Processed data saved to {output_path}")
    print(f"Final record count: {len(df)}")

if __name__ == '__main__':
    main()
