#!/usr/bin/env python3
"""Data validation utilities."""

import pandas as pd
import sys

def check_missing_values(df, threshold=0.05):
    """Check if any column has more than threshold% missing values."""
    missing_pct = df.isnull().sum() / len(df)
    issues = missing_pct[missing_pct > threshold]
    return issues.to_dict() if len(issues) > 0 else None

def check_duplicates(df, key_columns):
    """Check for duplicate records based on key columns."""
    duplicates = df[df.duplicated(subset=key_columns, keep=False)]
    return len(duplicates)

def validate_numeric_ranges(df, column, min_val, max_val):
    """Validate that numeric column is within expected range."""
    out_of_range = df[(df[column] < min_val) | (df[column] > max_val)]
    return len(out_of_range)

def run_validation(filepath):
    """Run all validation checks on a CSV file."""
    df = pd.read_csv(filepath)
    results = {
        'row_count': len(df),
        'missing_values': check_missing_values(df),
        'duplicate_transactions': check_duplicates(df, ['transaction_id']),
        'invalid_quantities': validate_numeric_ranges(df, 'quantity', 1, 1000),
        'invalid_prices': validate_numeric_ranges(df, 'unit_price', 0.01, 10000)
    }
    return results

if __name__ == '__main__':
    filepath = sys.argv[1] if len(sys.argv) > 1 else '/tmp/analysis/data/raw/sales.csv'
    results = run_validation(filepath)
    for key, value in results.items():
        print(f"{key}: {value}")
