from datetime import datetime

class DataProcessor:
    def __init__(self, config):
        self.batch_size = config.get('batch_size', 100)
        self.validate_strict = config.get('strict_validation', True)

    def transform(self, records):
        results = []
        for batch in self._batch(records, self.batch_size):
            processed = [self._process_record(r) for r in batch]
            results.extend(processed)
        return results

    def _process_record(self, record):
        return {
            'id': record['id'],
            'value': float(record['amount']) * 1.1,
            'processed_at': datetime.now().isoformat()
        }

    def _batch(self, items, size):
        for i in range(0, len(items), size):
            yield items[i:i+size]

def validate_input(data):
