from utils import DatabasePool, CacheManager
from auth import SessionHandler, TokenValidator

logger = logging.getLogger(__name__)

class ApplicationServer:
    def __init__(self, config_path):
        self.config = self._load_config(config_path)
        self.db_pool = DatabasePool(self.config['database'])
        self.cache = CacheManager(self.config['cache'])
        self.session_handler = SessionHandler(
            secret_key=self.config['security']['session_secret'],
            expiry_hours=self.config['security']['session_expiry_hours']
        )

    def _load_config(self, path):
        with open(path) as f:
            return json.load(f)

    def handle_request(self, request):
        session = self.session_handler.validate(request.headers.get('Authorization'))
        if not session:
            return {'error': 'Unauthorized', 'code': 401}

        user_data = self.cache.get(f"user:{session.user_id}")
        if not user_data:
            user_data = self.db_pool.query(
                "SELECT * FROM users WHERE id = %s",
                [session.user_id]
            )
            self.cache.set(f"user:{session.user_id}", user_data, ttl=300)

        return {'status': 'ok', 'user': user_data}

if __name__ == '__main__':
