import jwt
import hashlib
from datetime import datetime, timedelta
from dataclasses import dataclass

@dataclass
class Session:
    user_id: int
    username: str
    roles: list
    created_at: datetime
    expires_at: datetime

class SessionHandler:
    def __init__(self, secret_key, expiry_hours=24):
        self.secret_key = secret_key
        self.expiry_hours = expiry_hours

    def create_session(self, user_id, username, roles):
        now = datetime.utcnow()
        payload = {
            'user_id': user_id,
            'username': username,
            'roles': roles,
            'iat': now.timestamp(),
            'exp': (now + timedelta(hours=self.expiry_hours)).timestamp()
        }
        return jwt.encode(payload, self.secret_key, algorithm='HS256')

    def validate(self, token):
        if not token or not token.startswith('Bearer '):
            return None
        try:
            payload = jwt.decode(
                token[7:],
                self.secret_key,
                algorithms=['HS256']
            )
            return Session(
                user_id=payload['user_id'],
                username=payload['username'],
                roles=payload['roles'],
                created_at=datetime.fromtimestamp(payload['iat']),
                expires_at=datetime.fromtimestamp(payload['exp'])
            )
        except jwt.InvalidTokenError:
            return None

class TokenValidator:
    def __init__(self, public_key):
        self.public_key = public_key

    def verify_api_key(self, key):
        # Hash and compare against stored keys
        hashed = hashlib.sha256(key.encode()).hexdigest()
        return self._lookup_key(hashed)

