        with open(path) as f:
            return yaml.safe_load(f)

    def process_file(self, file_path):
        """Process incoming data file with security checks."""
        file_size = os.path.getsize(file_path)

        if file_size > self.max_file_size:
            raise ValueError(f"File {file_path} ({file_size} bytes) exceeds maximum size {self.max_file_size}")

        if self.config['security']['strict_validation']:
            if not validate_schema(file_path):
                raise ValueError(f"Schema validation failed for {file_path}")

        if self.config['security']['checksum_verification']:
            if not check_file_integrity(file_path):
                raise ValueError(f"Checksum verification failed for {file_path}")

        # Process the data
        with open(file_path, 'r') as f:
            data = f.readlines()

        processed = self._transform(data)
        self._log_processing(file_path, len(processed))
        return processed

    def _transform(self, data):
        return [line.strip().upper() for line in data if line.strip()]

    def _log_processing(self, path, count):
        from datetime import datetime
        with open('/tmp/project/logs/pipeline.log', 'a') as f:
