from utils import setup_logging, validate_request

app = Flask(__name__)
logger = logging.getLogger(__name__)

@app.route('/api/process', methods=['POST'])
def process_data():
    try:
        data = request.get_json()
        if not validate_request(data):
            logger.warning(f"Invalid request from {request.remote_addr}")
            return jsonify({'error': 'Invalid request'}), 400

        logger.info(f"Processing batch of {len(data['items'])} items")
        results = [process_item(item) for item in data['items']]
        return jsonify({'status': 'success', 'processed': len(results)})
    except Exception as e:
        logger.error(f"Processing error: {str(e)}", exc_info=True)
        return jsonify({'error': 'Internal server error'}), 500

def process_item(item):
    if item.get('priority') == 'high':
        logger.debug(f"High priority processing for item {item['id']}")
    return {'id': item['id'], 'status': 'processed'}

if __name__ == '__main__':
    setup_logging()
    logger.info("Starting application server on port 8080")
    app.run(host='0.0.0.0', port=8080, threaded=True)
