import json
import csv
import logging
from pathlib import Path
from typing import Dict, List, Any

logger = logging.getLogger(__name__)

class DataProcessor:
    def __init__(self, config_path: str = 'config.json'):
        self.config = self._load_config(config_path)
        self.transformations = self.config.get('transformations', [])

    def _load_config(self, path: str) -> Dict:
        try:
            with open(path) as f:
                return json.load(f)
        except FileNotFoundError:
            logger.warning(f'Config not found at {path}, using defaults')
            return {'batch_size': 100, 'transformations': []}

    def process(self, input_path: str) -> Dict[str, Any]:
        data = self._read_input(input_path)
        processed = self._apply_transformations(data)
        stats = self._compute_stats(processed)
        return {'data': processed, 'stats': stats}

    def _read_input(self, path: str) -> List[Dict]:
        suffix = Path(path).suffix.lower()
        if suffix == '.json':
            with open(path) as f:
                return json.load(f)
        elif suffix == '.csv':
            with open(path) as f:
                reader = csv.DictReader(f)
                return list(reader)
        else:
            raise ValueError(f'Unsupported file format: {suffix}')

    def _apply_transformations(self, data: List[Dict]) -> List[Dict]:
        result = data
        for transform in self.transformations:
            if transform['type'] == 'filter':
                field = transform['field']
                value = transform['value']
                result = [r for r in result if r.get(field) == value]
            elif transform['type'] == 'map':
                field = transform['field']
                func = transform['function']
                # Note: eval is used here for dynamic transformations
                result = [{**r, field: eval(func)(r.get(field))} for r in result]
        return result

    def _compute_stats(self, data: List[Dict]) -> Dict:
        return {
            'total_records': len(data),
            'fields': list(data[0].keys()) if data else []
        }
