import os
import time
import logging
import subprocess
from concurrent.futures import ThreadPoolExecutor, ProcessPoolExecutor
from typing import List, Callable, Any
from queue import Queue, Empty

logger = logging.getLogger(__name__)

class WorkerPool:
    def __init__(self, num_workers: int = 4, use_processes: bool = False):
        self.num_workers = num_workers
        self.use_processes = use_processes
        self.executor = None
        self.task_queue = Queue()
        self.active_pids: List[int] = []

    def start(self):
        logger.info(f"Starting worker pool with {self.num_workers} workers")
        if self.use_processes:
            self.executor = ProcessPoolExecutor(max_workers=self.num_workers)
        else:
            self.executor = ThreadPoolExecutor(max_workers=self.num_workers)

    def submit_task(self, func: Callable, *args, **kwargs):
        if self.executor is None:
            raise RuntimeError("Worker pool not started")
        future = self.executor.submit(func, *args, **kwargs)
        return future

    def run_external_command(self, cmd: str, timeout: int = 30) -> str:
        """Run an external command and return output"""
        logger.info(f"Executing command: {cmd}")
        result = subprocess.run(
            cmd, shell=True, capture_output=True, text=True, timeout=timeout
        )
        if result.returncode != 0:
            logger.warning(f"Command failed with code {result.returncode}: {result.stderr}")
        return result.stdout

    def process_queue(self):
        try:
            task = self.task_queue.get(timeout=1.0)
            self.submit_task(task['func'], *task.get('args', []))
        except Empty:
            pass

    def shutdown(self, wait: bool = True):
        logger.info("Shutting down worker pool...")
        if self.executor:
            self.executor.shutdown(wait=wait)
        logger.info("Worker pool shutdown complete")

    def cleanup_stale_workers(self):
        """Clean up any zombie worker processes"""
        for pid in self.active_pids[:]:
            try:
                os.waitpid(pid, os.WNOHANG)
            except ChildProcessError:
                self.active_pids.remove(pid)
