class ProcessManager:
    """Manages application processes and their lifecycle"""

    def __init__(self, pid_file: str = '/tmp/project/logs/app.pid'):
        self.pid_file = pid_file
        self.managed_pids: List[int] = []

    def get_current_pid(self) -> int:
        return os.getpid()

    def write_pid_file(self):
        pid = self.get_current_pid()
        with open(self.pid_file, 'w') as f:
            f.write(str(pid))
        logger.info(f"Wrote PID {pid} to {self.pid_file}")

    def read_pid_file(self) -> Optional[int]:
        try:
            with open(self.pid_file, 'r') as f:
                return int(f.read().strip())
        except (FileNotFoundError, ValueError):
            return None

    def is_process_running(self, pid: int) -> bool:
        try:
            process = psutil.Process(pid)
            return process.is_running()
        except psutil.NoSuchProcess:
            return False

    def send_signal_to_pid(self, pid: int, sig: int):
        """Send a signal to a specific process"""
        try:
            os.kill(pid, sig)
            logger.info(f"Sent signal {sig} to process {pid}")
        except ProcessLookupError:
            logger.warning(f"Process {pid} not found")
        except PermissionError:
            logger.error(f"Permission denied sending signal to {pid}")

    def stop_gracefully(self, pid: int, timeout: int = 30):
        """Attempt graceful shutdown, then force if needed"""
        self.send_signal_to_pid(pid, signal.SIGTERM)
        # Wait for graceful shutdown
        import time
        for _ in range(timeout):
            if not self.is_process_running(pid):
                logger.info(f"Process {pid} terminated gracefully")
                return True
            time.sleep(1)
        # Force kill if still running
        logger.warning(f"Process {pid} did not stop gracefully, forcing...")
        self.send_signal_to_pid(pid, signal.SIGKILL)
        return False
