import re
import phonenumbers
from typing import Optional

def validate_phone(phone_str: str) -> Optional[str]:
    """Validate and format phone number to E.164."""
    if not phone_str or phone_str.strip() == '':
        return None

    try:
        # Remove any non-digit characters except +
        cleaned = re.sub(r'[^\d+]', '', phone_str)
        if not cleaned.startswith('+'):
            cleaned = '+1' + cleaned  # Default to US

        parsed = phonenumbers.parse(cleaned, None)
        if phonenumbers.is_valid_number(parsed):
            return phonenumbers.format_number(parsed, phonenumbers.PhoneNumberFormat.E164)
    except Exception:
        pass
    return phone_str

def sanitize_string(value: str) -> str:
    """Remove null bytes and control characters."""
    if not value:
        return ''
    # Remove null bytes and other control chars except newline and tab
    return ''.join(char for char in value if char == '\n' or char == '\t' or (char >= ' ' and char <= '~') or ord(char) > 127)
