#!/usr/bin/env python3
"""Data validation utilities."""

import pandas as pd
from typing import List, Dict, Any

def check_missing_values(df: pd.DataFrame) -> Dict[str, int]:
    """Return count of missing values per column."""
    return df.isnull().sum().to_dict()

def check_duplicates(df: pd.DataFrame, subset: List[str]) -> int:
    """Count duplicate rows based on subset of columns."""
    return df.duplicated(subset=subset).sum()

def validate_numeric_range(df: pd.DataFrame, column: str, min_val: float, max_val: float) -> bool:
    """Check if all values in column are within expected range."""
    return df[column].between(min_val, max_val).all()

def generate_validation_report(df: pd.DataFrame, key_columns: List[str]) -> Dict[str, Any]:
    """Generate comprehensive validation report."""
    return {
        'row_count': len(df),
        'missing_values': check_missing_values(df),
        'duplicates': check_duplicates(df, key_columns),
        'columns': list(df.columns),
        'dtypes': df.dtypes.astype(str).to_dict()
    }
