import json
import pathlib
import urllib.request

BOOKMARKS = pathlib.Path('/tmp/research/bookmarks.json')
OUTPUT = pathlib.Path('/tmp/research/archive/headers.json')


def load_urls():
    data = json.loads(BOOKMARKS.read_text())
    urls = []
    for topic in data['topics']:
        urls.extend(topic['urls'])
    return urls


def fetch_headers(url):
    req = urllib.request.Request(url, method='HEAD', headers={'User-Agent': 'ResearchBot/1.0'})
    with urllib.request.urlopen(req, timeout=10) as resp:
        return {
            'url': url,
            'status': resp.status,
            'content_type': resp.headers.get('Content-Type')
        }


def main():
    results = []
    for url in load_urls():
        try:
            results.append(fetch_headers(url))
        except Exception as exc:
            results.append({'url': url, 'error': str(exc)})
    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    OUTPUT.write_text(json.dumps(results, indent=2))


if __name__ == '__main__':
    main()
EOF

