    "fluentd": {"memory_mb": 512, "throughput": "medium", "structured": True, "reliability": "medium"},
    "fluent-bit": {"memory_mb": 15, "throughput": "high", "structured": True, "reliability": "high"},
    "promtail": {"memory_mb": 60, "throughput": "medium", "structured": True, "reliability": "medium"}
}

def evaluate(criteria):
    """Score candidates against requirements."""
    scores = {}
    for name, specs in candidates.items():
        score = 0
        if specs["memory_mb"] < 50:
            score += 2
        if specs["structured"]:
            score += 1
        if specs["reliability"] == "high":
            score += 2
        scores[name] = score
    return sorted(scores.items(), key=lambda x: x[1], reverse=True)

if __name__ == "__main__":
    results = evaluate(None)
    for agent, score in results:
        print(f"{agent}: {score}/5")
